// Third Party
import { formatDate, renderTooltip } from "aa-geuthur-react";
import type { BaseColumnDef } from "aa-geuthur-react";
import type { TFunction } from "i18next";
import { History, Trash2, Users } from "lucide-react";
import { Badge, Button, ButtonGroup } from "react-bootstrap";

// AA TaxSystem
import type { components } from "@/Api/OpenApi";
import { OwnerPortrait } from "@/Components/Base/OwnerPortrait";

export type MemberRow = components["schemas"]["MembersSchema"];

export interface MemberColumnsOptions {
  t: TFunction;
  onOpenAlts: (member: MemberRow) => void;
  onHistory: (member: MemberRow) => void;
  onDeleteMissing: (member: MemberRow) => void;
}

export function getMemberColumns({
  t,
  onOpenAlts,
  onHistory,
  onDeleteMissing,
}: MemberColumnsOptions): BaseColumnDef<MemberRow>[] {
  return [
    {
      id: "character",
      header: t("Character"),
      accessorFn: (row) => row.character?.character_name,
      cell: ({ row }) => {
        const openInvoices = row.original.open_invoices ?? 0;
        const alts = row.original.alts ?? [];
        return (
          <div className="d-flex align-items-center gap-2">
            <OwnerPortrait
              src={row.original.character?.character_portrait}
              alt={row.original.character?.character_name}
              size="sm"
            />
            <span className="fw-semibold">{row.original.character?.character_name}</span>
            {alts.length > 0 &&
              renderTooltip(
                t("Show {{count}} alt character(s)", {
                  count: alts.length,
                }),
                <Button
                  variant="secondary"
                  size="sm"
                  className="aa-compact d-inline-flex align-items-center gap-1 py-0 px-2"
                  onClick={(e) => {
                    e.stopPropagation();
                    onOpenAlts(row.original);
                  }}
                >
                  <Users size={12} />
                  <span>
                    {alts.length} {t("Alts")}
                  </span>
                </Button>,
              )}
            {openInvoices > 0 &&
              renderTooltip(
                t("{{count}} pending payment(s) to review/approve", {
                  count: openInvoices,
                }),
                <Button
                  variant="warning"
                  size="sm"
                  className="aa-pulse"
                  onClick={(e) => {
                    e.stopPropagation();
                    onHistory(row.original);
                  }}
                >
                  <span className="aa-pending-dot-container">
                    <span className="aa-pending-dot-ping" />
                    <span className="aa-pending-dot-core" />
                  </span>
                  <span>
                    {openInvoices} {t("Pending")}
                  </span>
                </Button>,
              )}
          </div>
        );
      },
    },
    {
      id: "status",
      header: t("Status"),
      accessorKey: "status",
      cell: ({ getValue }) => (
        <Badge bg="secondary">{String(getValue() || "")}</Badge>
      ),
    },
    {
      id: "missing",
      header: t("Missing"),
      accessorKey: "is_missing",
      cell: ({ getValue }) => {
        const isMissing = Boolean(getValue());
        return isMissing ? (
          <Badge bg="danger">{t("Missing")}</Badge>
        ) : (
          <Badge bg="success">{t("Active")}</Badge>
        );
      },
    },
    {
      id: "joined",
      header: t("Joined"),
      accessorKey: "joined",
      cell: ({ getValue }) => {
        const val = getValue();
        if (!val) return "—";
        return formatDate(String(val), { dateStyle: "medium" });
      },
    },
    {
      id: "actions",
      header: t("Actions"),
      cell: ({ row }) => (
        <ButtonGroup size="sm">
          {row.original.character?.character_id &&
            renderTooltip(
              t("Payment History & Activities"),
              <Button
                variant="info"
                aria-label={t("History")}
                onClick={() => onHistory(row.original)}
              >
                <History size={14} />
              </Button>,
            )}
          {row.original.is_missing &&
            row.original.character?.character_id &&
            renderTooltip(
              t("Delete"),
              <Button
                variant="danger"
                aria-label={t("Delete")}
                onClick={() => onDeleteMissing(row.original)}
              >
                <Trash2 size={14} />
              </Button>,
            )}
        </ButtonGroup>
      ),
    },
  ];
}
