// React
import { useMemo, useState } from "react";

// Third Party
import {
  BaseModal,
  BaseTable,
  FilterButtonGroup,
  ModalSize,
  formatCompactNumber,
} from "aa-geuthur-react";
import { CheckCircle2, DollarSign, UserCheck, XCircle } from "lucide-react";
import { Button, Form, Spinner } from "react-bootstrap";
import { useTranslation } from "react-i18next";

// AA TaxSystem
import type { components } from "@/Api/OpenApi";
import { OwnerPortrait } from "@/Components/Base/OwnerPortrait";
import { SearchInput } from "@/Components/Base/SearchInput";
import { useAccountActions, useTaxAccounts } from "@/Components/OwnerManage/Hooks";
import { MemberPaymentsModal } from "@/Components/OwnerManage/Modals/MemberPaymentsModal";
import { getAccountColumns } from "@/Components/Tables";
import { useTableSearchState } from "@/Hooks/useTaxsystemState";

interface AccountsTabProps {
  ownerId: number;
}

type AccountRow = components["schemas"]["PaymentSystemSchema"];
type PaidFilter = "all" | "paid" | "unpaid";

export function AccountsTab({ ownerId }: AccountsTabProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useTableSearchState("accountSearch");
  const [paidFilter, setPaidFilter] = useState<PaidFilter>("all");

  // Modal State for switching account
  const [selectedAccount, setSelectedAccount] = useState<AccountRow | null>(null);
  const [newStatus, setNewStatus] = useState("active");
  const [comment, setComment] = useState("");

  // Modal State for custom payment
  const [paymentAccount, setPaymentAccount] = useState<AccountRow | null>(null);
  const [paymentAmount, setPaymentAmount] = useState<number | "">("");
  const [paymentComment, setPaymentComment] = useState("");

  // Modal State for member payments / activities
  const [historyMember, setHistoryMember] = useState<{
    characterId: number;
    characterName: string;
    characterPortrait?: string;
  } | null>(null);

  const { data: accounts, isLoading, isError } = useTaxAccounts(ownerId);
  const accountActions = useAccountActions(ownerId, {
    onSwitched: () => {
      setSelectedAccount(null);
      setComment("");
    },
    onPaymentAdded: () => {
      setPaymentAccount(null);
      setPaymentAmount("");
      setPaymentComment("");
    },
  });

  const filteredAccounts = useMemo(() => {
    if (!accounts) return [];
    let list = accounts;
    if (paidFilter === "paid") {
      list = list.filter((acc) => Boolean(acc.has_paid));
    } else if (paidFilter === "unpaid") {
      list = list.filter((acc) => !acc.has_paid);
    }
    if (!search) return list;
    const q = search.toLowerCase();
    return list.filter(
      (acc) =>
        acc.account?.character_name?.toLowerCase().includes(q) ||
        acc.status?.toLowerCase().includes(q),
    );
  }, [accounts, search, paidFilter]);

  const columns = useMemo(
    () =>
      getAccountColumns({
        t,
        onHistory: (acc) => {
          if (acc.account?.character_id) {
            setHistoryMember({
              characterId: acc.account.character_id,
              characterName: acc.account.character_name || "",
              characterPortrait: acc.account.character_portrait,
            });
          }
        },
        onAddPayment: (acc) => {
          setPaymentAccount(acc);
          setPaymentAmount("");
          setPaymentComment("");
        },
        onSwitchStatus: (acc) => {
          setSelectedAccount(acc);
          setNewStatus(acc.is_active ? "deactivated" : "active");
        },
      }),
    [t],
  );

  return (
    <div className="mt-3">
      <div className="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3">
        <div className="d-flex flex-wrap align-items-center gap-2">
          <SearchInput
            value={search}
            onChange={setSearch}
            placeholder={t("Filter accounts by name or status…")}
          />

          <FilterButtonGroup<PaidFilter>
            value={paidFilter}
            onChange={(val) => setPaidFilter(val)}
            options={[
              { value: "all", label: t("All") },
              {
                value: "paid",
                label: t("Paid"),
                icon: <CheckCircle2 size={13} />,
              },
              {
                value: "unpaid",
                label: t("Unpaid"),
                icon: <XCircle size={13} />,
              },
            ]}
            ariaLabel="Filter accounts by payment status"
          />
        </div>
      </div>

      <BaseTable
        data={filteredAccounts}
        columns={columns}
        isFetching={isLoading}
        isError={isError}
        emptyText={t("No tax accounts found.")}
        variant="light"
      />

      {/* Switch Account Modal */}
      {selectedAccount && (
        <BaseModal bodyClassName="aa-panel"
          show={!!selectedAccount}
          onHide={() => setSelectedAccount(null)}
          size={ModalSize.medium}
          title={
            <>
              <UserCheck size={18} className="me-2 text-primary" />
              {t("Switch Tax Account")}: {selectedAccount.account?.character_name}
            </>
          }
          footer={
            <>
              <Button
                variant="secondary"
                onClick={() => setSelectedAccount(null)}
              >
                {t("Cancel")}
              </Button>
              <Button
                variant="primary"
                disabled={accountActions.isSwitching}
                onClick={() => {
                  if (selectedAccount.account_id) {
                    accountActions.switchAccount({
                      accountPk: selectedAccount.account_id,
                    });
                  }
                }}
              >
                {accountActions.isSwitching && <Spinner size="sm" animation="border" className="me-1" />}
                {t("Save Changes")}
              </Button>
            </>
          }
        >
          <Form.Group className="mb-3">
            <Form.Label>{t("New Status")}</Form.Label>
            <Form.Select
              value={newStatus}
              onChange={(e) => setNewStatus(e.target.value)}
              className="bg-dark text-light border-secondary"
            >
              <option value="active">{t("Active")}</option>
              <option value="deactivated">{t("Deactivated")}</option>
            </Form.Select>
          </Form.Group>
          <Form.Group className="mb-3">
            <Form.Label>{t("Comment / Reason")}</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder={t("Optional comment for admin history…")}
              className="bg-dark text-light border-secondary"
            />
          </Form.Group>
        </BaseModal>
      )}

      {/* Add Custom Payment Modal */}
      {paymentAccount && (
        <BaseModal bodyClassName="aa-panel"
          show={!!paymentAccount}
          onHide={() => setPaymentAccount(null)}
          size={ModalSize.medium}
          title={
            <div className="d-flex align-items-center gap-2 text-success">
              <DollarSign size={18} />
              {t("Add Custom Payment")}
            </div>
          }
          footer={
            <>
              <Button
                variant="secondary"
                onClick={() => setPaymentAccount(null)}
              >
                {t("Cancel")}
              </Button>
              <Button
                variant="success"
                disabled={
                  !paymentAmount ||
                  Number(paymentAmount) <= 0 ||
                  !paymentComment.trim() ||
                  accountActions.isAddingPayment
                }
                onClick={() => {
                  if (paymentAccount?.account_id) {
                    accountActions.addPayment({
                      accountPk: paymentAccount.account_id,
                      amount: Number(paymentAmount),
                      comment: paymentComment,
                    });
                  }
                }}
              >
                {accountActions.isAddingPayment && <Spinner size="sm" animation="border" className="me-1" />}
                {t("Add Payment")}
              </Button>
            </>
          }
        >
          <div className="d-flex align-items-center gap-3 mb-3 p-2 bg-black bg-opacity-25 rounded border border-secondary">
            <OwnerPortrait
              src={paymentAccount.account?.character_portrait}
              alt={paymentAccount.account?.character_name}
              size="md"
            />
            <div>
              <div className="fw-semibold text-light">{paymentAccount.account?.character_name}</div>
              <div className="small text-muted">
                {t("Current Balance")}:{" "}
                <span className="text-info">{formatCompactNumber(Number(paymentAccount.deposit || 0), "ISK")}</span>
              </div>
            </div>
          </div>

          <Form.Group className="mb-3">
            <Form.Label>{t("Amount (ISK)")}</Form.Label>
            <Form.Control
              type="number"
              min="1"
              step="1"
              value={paymentAmount}
              onChange={(e) => setPaymentAmount(e.target.value === "" ? "" : Number(e.target.value))}
              placeholder={t("e.g. 10000000")}
              className="bg-dark text-light border-secondary"
              autoFocus
            />
            {typeof paymentAmount === "number" && paymentAmount > 0 && (
              <Form.Text className="text-info small">
                ≈ {formatCompactNumber(paymentAmount, "ISK")}
              </Form.Text>
            )}
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>{t("Reason / Comment")}</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              value={paymentComment}
              onChange={(e) => setPaymentComment(e.target.value)}
              placeholder={t("Reason for manual payment addition…")}
              className="bg-dark text-light border-secondary"
              required
            />
          </Form.Group>
        </BaseModal>
      )}

      {historyMember && (
        <MemberPaymentsModal
          ownerId={ownerId}
          characterId={historyMember.characterId}
          characterName={historyMember.characterName}
          characterPortrait={historyMember.characterPortrait}
          show
          onClose={() => setHistoryMember(null)}
        />
      )}
    </div>
  );
}

export default AccountsTab;
